import{_ as d,C as a,o as t,c,j as i,a as r,E as o,a5 as s,b as E,w as h,a6 as u}from"./chunks/framework.D_J2JZBr.js";const P=JSON.parse('{"title":"EE113 数字集成电路 I 及实验","description":"从 MOSFET 与 CMOS 门电路，到时延功耗、全定制版图和寄生后仿的课程指南。","frontmatter":{"title":"EE113 数字集成电路 I 及实验","description":"从 MOSFET 与 CMOS 门电路，到时延功耗、全定制版图和寄生后仿的课程指南。"},"headers":[],"relativePath":"shanghaitech/courses/ee113.md","filePath":"shanghaitech/courses/ee113.md","lastUpdated":1795531638000}'),g={name:"shanghaitech/courses/ee113.md"};function p(b,e,m,f,C,_){const l=a("CourseTable"),n=a("Mermaid");return t(),c("div",null,[e[1]||(e[1]=i("h1",{id:"ee113-数字集成电路-i-及实验",tabindex:"-1"},[r("EE113 数字集成电路 I 及实验 "),i("a",{class:"header-anchor",href:"#ee113-数字集成电路-i-及实验","aria-label":'Permalink to "EE113 数字集成电路 I 及实验"'},"​")],-1)),o(l,{codes:"EE113,EE113L"}),e[2]||(e[2]=s('<p>课程表采用 <strong>2026–2027 学年</strong>开课数据；内容与考核经验对应 <strong>2026 秋版本</strong>。往届版本教师可能不同，EE113L 独立设课，不能因本页合并介绍而省略选课确认。</p><h2 id="课程定位" tabindex="-1">课程定位 <a class="header-anchor" href="#课程定位" aria-label="Permalink to &quot;课程定位&quot;">​</a></h2><p><a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee115b">数字电路</a>中的一个逻辑门，在本课里会被拆回晶体管、电阻、电容与真实版图。你将学习为什么同样的逻辑功能会有不同的速度、功耗、面积和可靠性。</p><p>官方表中 EE113 先修写为 EE111、EE115；这里保留其原始编号，不擅自解释为只要求 EE115A 或 EE115B。学习上建议同时熟悉基本电路、MOS 工作区、组合与时序逻辑。后续可接 EE213、可测性设计，以及<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee291f">EE291F</a>。<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee115a">模拟电路</a>的小信号分析也能帮助理解器件与负载。</p><h2 id="内容主线" tabindex="-1">内容主线 <a class="header-anchor" href="#内容主线" aria-label="Permalink to &quot;内容主线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>内容</th><th>学习抓手</th></tr></thead><tbody><tr><td>器件与流程</td><td>MOS I–V、短沟道效应、CMOS 缩放、VLSI 流程</td><td>区分模型假设与真实工艺限制</td></tr><tr><td>反相器</td><td>电压传输特性、翻转阈值、噪声容限</td><td>从工作区和电流平衡理解信号再生</td></tr><tr><td>时延与功耗</td><td>RC 模型、寄生电容、动态 / 短路 / 漏电功耗</td><td>明确输入活动、负载、电源与测量条件</td></tr><tr><td>逻辑实现</td><td>静态 CMOS、动态逻辑、传输门</td><td>追踪导通路径与弱电平、共享电荷等风险</td></tr><tr><td>优化与算术</td><td>尺寸优化、逻辑努力（Logical Effort）、加法器与前缀结构</td><td>比较路径延时、扇出与布线代价</td></tr><tr><td>时序与版图</td><td>锁存器 / 触发器、建立保持时间、设计规则</td><td>连接电路时序与物理实现</td></tr></tbody></table><p>一项优化需要明确“优化什么、代价是什么”。加大尺寸可能降低某段驱动电阻，也会增加前级负载；不能只看局部门延时。</p><h2 id="实验-项目" tabindex="-1">实验 / 项目 <a class="header-anchor" href="#实验-项目" aria-label="Permalink to &quot;实验 / 项目&quot;">​</a></h2><h3 id="ee113l-从反相器走完整流程" tabindex="-1">EE113L：从反相器走完整流程 <a class="header-anchor" href="#ee113l-从反相器走完整流程" aria-label="Permalink to &quot;EE113L：从反相器走完整流程&quot;">​</a></h3><p>2026 秋 Lab0 给出的路线包括器件 I–V 仿真、反相器原理图与分析、反相器版图、寄生提取与后仿，再到复杂门设计及版图集成。工具为 Virtuoso、Spectre / HSPICE 与 Calibre。</p>',10)),(t(),E(u,null,{default:h(()=>[o(n,{id:"mermaid-115",class:"mermaid",graph:"flowchart%20TD%0A%20A%5B%E8%A7%84%E6%A0%BC%5D%20--%3E%20B%5B%E5%8E%9F%E7%90%86%E5%9B%BE%5D%0A%20B%20--%3E%20C%5B%E5%89%8D%E4%BB%BF%5D%0A%20C%20--%3E%20D%5B%E7%89%88%E5%9B%BE%5D%0A%20D%20--%3E%20E%5BDRC%20%E4%B8%8E%20LVS%5D%0A%20E%20--%3E%20F%5B%E5%AF%84%E7%94%9F%E6%8F%90%E5%8F%96%5D%0A%20F%20--%3E%20G%5B%E5%90%8E%E4%BB%BF%E4%B8%8E%E5%AF%B9%E6%AF%94%5D%0A"})]),fallback:h(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=s('<p>设计规则检查（DRC）回答几何是否合规，版图与原理图对比（LVS）核对提取电路与原理图的一致性；两者均不能代替后仿验证时序与性能。</p><h3 id="final-project-全定制-cpu" tabindex="-1">Final Project：全定制 CPU <a class="header-anchor" href="#final-project-全定制-cpu" aria-label="Permalink to &quot;Final Project：全定制 CPU&quot;">​</a></h3><p>2026 秋项目笔记记录了一颗 <strong>16-bit 单周期 CPU</strong> 的晶体管级设计，覆盖程序计数器、寄存器堆、ALU、控制与顶层接口，以及原理图、前仿、全定制版图、DRC / LVS / 寄生提取和后仿。它<strong>不是</strong>把 RTL 交给综合工具自动生成的项目。</p><p>建议先冻结接口与指令语义，建立可检查的行为参考；叶子单元通过后再集成模块。前仿正确不代表版图已通过，DRC / LVS 通过也不代表寄生后仿满足性能。课程练习完成更不等于已经制造出芯片。</p><h2 id="教材与资源" tabindex="-1">教材与资源 <a class="header-anchor" href="#教材与资源" aria-label="Permalink to &quot;教材与资源&quot;">​</a></h2><ul><li>Rabaey 等，<em>Digital Integrated Circuits: A Design Perspective</em>：课程说明中的主要参考。</li><li>Weste / Harris，<em>CMOS VLSI Design</em>：补充结构与设计方法。</li><li><a href="https://mooc.shanghaitech.edu.cn/" target="_blank" rel="noreferrer">上海科技大学 MOOC 入口</a>：按课程授权获取材料。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/tools/eda/commercial">商业 EDA</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/tools/development/">EDA 环境</a>：区分工具、许可证与工艺设计套件（PDK）的角色。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/cadence-summer">Cadence 暑期实训</a>：对照全定制流程与标准单元自动布局布线。</li></ul><h2 id="往届经验与建议" tabindex="-1">往届经验与建议 <a class="header-anchor" href="#往届经验与建议" aria-label="Permalink to &quot;往届经验与建议&quot;">​</a></h2><p><strong>2026 秋版本。</strong> 课程说明笔记记录 EE113 为作业 20%、期中 25%、期末 25%、项目 30%，另有额外加分规则；EE113L 笔记记录为 P/NP。两门课分别考核，具体规则以教师通知为准。</p><ul><li><strong>难点</strong>：近似 RC 模型、串并联门的最坏路径、尺寸与负载的相互影响，以及版图连通和寄生退化。</li><li><strong>准备</strong>：复习 MOS 工作区与电容充放电。先手算趋势，再用同一组条件仿真，不要让软件输出代替解释。</li><li><strong>工具链</strong>：尽早跑通建库、原理图、仿真、版图和检查的小闭环。保存设置、模型、测试输入与报告，别只保存最终截图。</li><li><strong>项目节奏</strong>：复用经过独立验证的单元；模块与顶层分层检查。给布线、LVS 调试、寄生后仿和报告留出时间。</li><li><strong>授权</strong>：PDK、规则文件和商业工具只能在获授权环境内使用；公开经验时不上传内部资料。</li></ul><h2 id="相关方向" tabindex="-1">相关方向 <a class="header-anchor" href="#相关方向" aria-label="Permalink to &quot;相关方向&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/digital-vlsi">数字 VLSI</a>：电路、时序与功耗优化。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/eda">EDA</a>：综合、物理设计与验证算法。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/devices">器件</a>：理解工艺缩放与器件模型边界。</li></ul><div class="info custom-block"><p class="custom-block-title">征集</p><p>如果你修过 EE113 / EE113L，欢迎通过<a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a>补充版本差异与可迁移的调试方法。不要上传 PDK、许可证信息或整套项目答案。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">SIST 2026–2027 学年开课表</a>：教师、学分与先修原文。</li><li>维护者 2026 秋笔记《数字集成电路 I》《EE113 Course Administration — 课程说明》《EE113L Lab0 — Introduction to IC Design &amp; EDA Flow》《EE113 Final Project — 16-bit Single-Cycle CPU》：主线、考核与项目类型；不采用笔记中的个人完成状态作为课程结论。</li></ul>',14))])}const D=d(g,[["render",p]]);export{P as __pageData,D as default};
